-- =============================================================================
-- REPTIC.CM — Revue de presse : articles de Digital Business Africa citant le REPTIC
-- (relevé du 21 novembre 2026, 35 articles, juin 2017 → octobre 2026).
-- Pour chaque article : titre, date, résumé rédigé pour le site et lien vers
-- l'article original (le texte complet reste chez Digital Business Africa).
--
-- 1. Les actualités actuelles sont ARCHIVÉES (retirées du site, récupérables).
-- 2. Les articles sont publiés dans la rubrique « Revue de presse ».
-- notified_at est renseigné : aucune notification ni e-mail n'est envoyé aux
-- membres pour ces publications. Rejouable sans doublon.
-- =============================================================================

insert into public.categories (kind, slug, name, description, position)
values ('news', 'revue-de-presse', 'Revue de presse', 'Articles de presse consacrés au REPTIC.CM', 10)
on conflict (kind, slug) do update set name = excluded.name, is_active = true;

-- 1. Retrait des actualités présentes (archivage, réversible)
update public.news set status = 'archived'
 where status <> 'archived' and slug not like 'presse-%';

-- 2. Revue de presse
insert into public.news (slug, title, excerpt, body, status, visibility, published_at, category_id, notified_at)
select v.slug, v.title, v.excerpt, v.body, 'published', 'public', v.published_at::timestamptz,
       (select id from public.categories where kind = 'news' and slug = 'revue-de-presse'), now()
  from (values
    ('presse-ia-le-cameroun-cherche-sa-place-dans-leconomie-numerique-a-lheure-de-lintelligence-artific', 'IA : Le Cameroun cherche sa place dans l’économie numérique à l’heure de l’intelligence artificielle', 'Au salon e-Gov''Africa de Yaoundé, le représentant du REPTIC a défendu une gouvernance numérique qui permette à chaque citoyen d''accéder au service public, où qu''il se trouve.', 'Au salon e-Gov''Africa de Yaoundé, le représentant du REPTIC a défendu une gouvernance numérique qui permette à chaque citoyen d''accéder au service public, où qu''il se trouve.

